// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    function setUp() public { c = new LiquidityPool(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(bytes32 what) public {
        vm.assume(what != "investmentManager");
        address mgrBefore = address(c.investmentManager());
        (bool ok, ) = address(c).call(abi.encodeWithSignature("file(bytes32,address)", what, address(0x1234)));
        address mgrAfter = address(c.investmentManager());
        assertTrue(ok == false || mgrAfter != mgrBefore);
    }
}
